def gen(rng):
    def fmt(n, edges):
        out = [f"{n} {len(edges)}"]
        out += [f"{a} {b}" for a, b in edges]
        return '\n'.join(out)
    def shuffled(n, edges):
        perm = list(range(n))
        rng.shuffle(perm)
        es = []
        for a, b in edges:
            a, b = perm[a], perm[b]
            es.append((a, b) if rng.random() < 0.5 else (b, a))
        rng.shuffle(es)
        return es
    def rand_tree(n, kind):
        es = []
        for i in range(1, n):
            if kind == 'path':
                p = i - 1
            elif kind == 'star':
                p = 0
            elif kind == 'deep':
                p = rng.randint(max(0, i - 3), i - 1)
            else:
                p = rng.randrange(i)
            es.append((p, i))
        return es
    def add_extra(n, es, k):
        have = {(min(a, b), max(a, b)) for a, b in es}
        out = es[:]
        tries = 0
        if n < 2:
            return out
        while k > 0 and tries < 20 * k + 1000:
            tries += 1
            a, b = rng.sample(range(n), 2)
            key = (min(a, b), max(a, b))
            if key in have:
                continue
            have.add(key)
            out.append((a, b))
            k -= 1
        return out
    tests = [fmt(1, []), fmt(2, []), fmt(2, [(0, 1)]), fmt(3, [(0, 1)]), fmt(3, [(0, 1), (1, 2), (0, 2)]), fmt(4, [(0, 1), (2, 3)]), fmt(4, [(0, 1), (1, 2), (0, 2)])]
    for _ in range(30):
        n = rng.randint(1, 12)
        kind = rng.choice(['rand', 'path', 'star', 'deep'])
        es = rand_tree(n, kind)
        mode = rng.random()
        if mode < 0.3:
            pass
        elif mode < 0.5 and n >= 2:
            es.pop(rng.randrange(len(es)))
        elif mode < 0.75 and n >= 3:
            es.pop(rng.randrange(len(es)))
            es = add_extra(n, es, 1)
        elif mode < 0.9:
            es = add_extra(n, es, rng.randint(1, 2))
        else:
            k = rng.randint(0, min(n * (n - 1) // 2, 2 * n))
            es = add_extra(n, [], k)
        tests.append(fmt(n, shuffled(n, es)))
    N = 10 ** 5
    for kind in ('rand', 'path', 'star', 'deep'):
        tests.append(fmt(N, shuffled(N, rand_tree(N, kind))))
    es = rand_tree(N, 'rand')
    es.pop(rng.randrange(len(es)))
    es = add_extra(N, es, 1)
    tests.append(fmt(N, shuffled(N, es)))
    es = rand_tree(N, 'path')
    es.pop(N // 2)
    tests.append(fmt(N, shuffled(N, es)))
    tests.append(fmt(N, shuffled(N, add_extra(N, [], 10 ** 5))))
    tests.append(fmt(N, shuffled(N, add_extra(N, rand_tree(N - 1, 'rand'), 1))))
    return tests

